import requests

def test_get_apihealth_returns_service_status():
    base_url = "http://localhost:5001"
    url = f"{base_url}/api/health"
    headers = {
        "Accept": "application/json"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "status" in data, "Response JSON missing 'status' field"
    assert isinstance(data["status"], str), "'status' field is not a string"
    assert data["status"].lower() in ["up", "ok", "running", "healthy", "available", "online"], \
        f"Unexpected status string: {data['status']}"

test_get_apihealth_returns_service_status()

import requests

BASE_URL = "http://localhost:5001"
TIMEOUT = 30
HEADERS = {
    "Accept": "application/json"
}

def test_TC002_get_apidebugtables_returns_database_tables_and_row_counts():
    url = f"{BASE_URL}/api/debug/tables"
    try:
        response = requests.get(url, headers=HEADERS, timeout=TIMEOUT)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        assert False, f"Request to {url} failed with exception: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        json_data = response.json()
    except ValueError:
        assert False, "Response content is not valid JSON"

    assert isinstance(json_data, dict), f"Expected JSON object (dict), got {type(json_data)}"

    # The JSON object should list tables and their row counts.
    # Assert that all keys are strings
    for table_name, row_count in json_data.items():
        assert isinstance(table_name, str), f"Table name should be string, got {type(table_name)}"
        # Check if row_count is int and non-negative, if not print warning but do not fail
        if not isinstance(row_count, int):
            # For the purpose of this test, accept non-int values but raise warning
            pass
        else:
            assert row_count >= 0, f"Row count for table '{table_name}' should be non-negative, got {row_count}"

test_TC002_get_apidebugtables_returns_database_tables_and_row_counts()

import requests

BASE_URL = "http://localhost:5001"
TIMEOUT = 30

def test_post_apisyncuser_upserts_user_record():
    url = f"{BASE_URL}/api/sync-user"
    headers = {
        "Content-Type": "application/json",
    }

    # Valid payload
    valid_payload = {
        "email": "testuser@example.com",
        "name": "Test User",
        "image": "https://example.com/avatar.png"
    }

    # Test valid request
    try:
        response = requests.post(url, json=valid_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status 200 but got {response.status_code}"
    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "id" in data, "Response JSON missing 'id'"
    assert data.get("email") == valid_payload["email"], f"Response email {data.get('email')} does not match request email {valid_payload['email']}"

    # Test invalid request missing email
    invalid_payload = {
        "name": "No Email User",
        "image": "https://example.com/avatar.png"
    }

    try:
        response_invalid = requests.post(url, json=invalid_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response_invalid.status_code == 400, f"Expected status 400 but got {response_invalid.status_code}"

test_post_apisyncuser_upserts_user_record()
